internal object DuaKoDraft7 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_jar_su" to DuaText("나쁜 이웃으로부터 도피하다", "오 알라, 나는 영주권에 있는 나쁜 이웃으로부터 당신께 피난처를 구합니다. 왜냐하면 여행 중인 이웃이 계속 나아가기 때문입니다.", "나쁜 이웃으로부터 보호하기 위해.", "선지자 ﷺ은 이것으로부터 피난처를 구하라고 명령했습니다."),
        "dua_ishfi_abdak" to DuaText("아픈 사람의 회복을 위해", "오 알라, 당신의 종을 치료하셔서 그가 당신을 위해 적과 맞서거나 당신을 위해 기도하러 걸어갈 수 있도록 해주세요.", "아픈 사람을 방문할 때.", "선지자 ﷺ은 병자를 위해 이렇게 말하라고 가르쳤습니다."),
        "dua_la_mania" to DuaText("누구도 당신이 주는 것을 보류할 수 없습니다", "어떠한 동반자도 없는 유일한 알라 외에는 경배받을 분이 없습니다. 그분의 통치권과 찬양도 그분에게 있으며, 그분은 만물을 다스리는 능력을 갖고 계십니다. 오 알라시여, 어느 누구도 당신이 주시는 것을 보류할 수 없고 당신이 보류한 것을 어느 누구도 줄 수 없으며 부자의 부는 당신에게 아무 소용이 없습니다.", "의무기도의 살람 이후.", "선지자 ﷺ은 모든 의무 기도 후에 이렇게 말했습니다."),
        "dua_slaughtering" to DuaText("동물을 도살할 때", "알라의 이름으로, 알라는 가장 위대하시다.", "동물을 희생시키거나 도살하는 경우.", "선지자 ﷺ은 희생 당시 Bismillah와 takbir를 말했습니다."),
        "dua_undressing" to DuaText("옷을 벗을 때", "알라의 이름으로.", "옷을 벗을 때(구슬이나 갈아입을 때)", "그것은 진의 눈과 사람의 은밀한 부분 사이의 막이 된다."),
        "dua_ilbas_jadidan" to DuaText("새 옷을 입은 사람을 보는 것", "새 옷을 입고 칭찬받을 만한 삶을 살고 순교자로 죽으십시오.", "새 옷을 입은 무슬림 형제를 보았을 때.", "예언자 ﷺ은 새 옷을 입은 우마르 (RA)을 보고 이 듀아를 만들었습니다."),
        "dua_hajj_la_riya" to DuaText("과시하지 않는 하지(Hajj)", "오 알라신이시여, 과시하지도 않고 명성을 구하지도 않는 하지(Hajj)를 만드세요.", "하지(Hajj)를 위한 의도를 세울 때 성실함을 위해.", "선지자 ﷺ은 하지(Hajj) 당시 이 두아를 만들었습니다."),
        "dua_q_muslimayni_laka" to DuaText("이브라힘과 이스마일의 두아 (AS) — 우리를 복종하게 만드세요", "우리 주님, 우리가 당신께 복종하게 하시고 우리 후손도 당신께 복종하는 민족이 되게 하소서. 우리의 예배의식을 보여주시고 우리의 회개를 받아들이십시오. 참으로 당신은 회개를 받아들이시는 자비로우신 분이십니다.", "자신과 후손에 대한 복종의 이중성.", "Ka'bah를 건설하는 동안 만들어진 두아."),
        "dua_q_iftah_baynana" to DuaText("Shu'aib의 Dua (AS) — 우리 사이의 심판관", "우리 주님, 우리와 우리 백성 사이를 진실로 판단하소서. 당신은 최고의 재판관이십니다.", "진실과 거짓 사이의 판단을 위해.", "그의 백성이 그를 거부했을 때 Shu'ayb (AS)의 이중."),
        "dua_q_la_akuna_zahiran" to DuaText("무사의 두아 (AS) - 결코 범죄자의 조력자는 아니다", "주님, 당신께서 제게 베푸신 은혜로 인해 저는 결코 범죄자들의 조력자가 되지 않겠습니다.", "알라의 축복에 대한 감사와 범죄자를 돕지 않겠다는 서약.", "회개 후 무사 (AS)의 서약."),
        "dua_q_nuh_unsurni" to DuaText("Dua of Nuh (AS) — 도와주세요, 그들이 나를 거부합니다", "나의 주님, 나를 도와주십시오. 그들이 나를 부인하였기 때문입니다.", "사람들이 당신을 부인하고 진리를 거부할 때.", "Nuh (AS)의 dua가 답변되었습니다."),
        "dua_q_ihkum_bil_haqq" to DuaText("나의 주님, 진리로 심판하소서", "주님, 진리로 판단하소서. 그리고 우리 주님은 당신이 묘사하는 것에 반대하여 도움을 구하는 가장 자비로운 분입니다.", "거짓과 허위 비난에 직면하여.", "예언자 ﷺ에게 가르친 두아."),
        "dua_ghalabatid_dayn" to DuaText("엄청난 빚과 적으로부터 피난처", "오 알라, 나는 빚에 눌리지 않고, 적에게 압도당하고, 적들의 칭찬으로부터 당신께 피난처를 구합니다.", "부채 부담과 적의 지배로부터 보호합니다.", "선지자 ﷺ은 이러한 것들로부터 피난처를 찾으곤 했습니다."),
        "dua_faqr_qillah_dhillah" to DuaText("가난과 굴욕으로부터의 도피처", "오 알라, 나는 가난과 궁핍, 굴욕으로부터, 그리고 다른 사람에게 해를 끼치거나 해를 당하는 것으로부터 당신께 피난처를 구합니다.", "고난과 궁핍과 굴욕으로부터 안전하기 위해서입니다.", "선지자 ﷺ이 가르친 피난처."),
        "dua_five_things_new_muslim" to DuaText("용서하다, 자비를 베풀다, 인도하다, 치유하다, 제공하다", "오 알라, 저를 용서하시고, 저에게 자비를 베푸시고, 저를 인도하시고, 저에게 행복을 주시고, 저를 공급해 주십시오.", "예언자 ﷺ은 기도와 함께 이 두아를 새로운 무슬림들에게 가르쳤습니다.", "선지자 ﷺ은 다음과 같이 말했습니다: 이 말씀은 이 세상과 내세를 위해 여러분을 위해 모입니다."),
        "dua_ruku_laka_raka_tu" to DuaText("인 루쿠 — 당신에게 나는 절했습니다", "오 알라, 나는 당신에게 절했고 당신을 믿었으며 당신에게 복종했습니다. 내 청각과 눈과 정신과 뼈와 힘줄이 당신 앞에 겸비해졌습니다.", "루쿠(특히 자발적인 기도)에서.", "선지자 ﷺ은 루쿠에서 이것을 낭송했습니다."),
        "dua_sujood_laka_sajadtu" to DuaText("인수주드 - 당신께 엎드립니다", "오 알라, 나는 당신에게 부복했으며 당신을 믿었고 당신에게 복종했습니다. 내 얼굴은 그것을 창조하시고, 형성하시고, 듣고 보게 하신 분에게 경배합니다. 최고의 창조자이신 알라는 축복을 받습니다.", "수주드(특히 자발적인 기도)에서.", "선지자 ﷺ은 이것을 sujood로 낭송했습니다."),
        "dua_ruku_sujood_subhanaka" to DuaText("우리 주님께 영광을 돌립니다 - 용서해주세요", "우리 주님이신 알라여, 당신께 영광을 돌리시고 찬양을 받으소서. 오 알라, 용서해주세요.", "루쿠와 수주드에서.", "아이샤 (RA): 선지자 ﷺ은 루쿠와 수주드에서 자주 이렇게 말했습니다."),
        "dua_q_musa_li_akhi" to DuaText("Dua of Musa (AS) — 나와 내 형제를 용서해주세요", "나의 주님, 나와 내 형제를 용서하시고 우리를 당신의 자비 안으로 인정해 주십시오. 왜냐하면 당신은 자비로운 자 중에 가장 자비로우시기 때문입니다.", "자신과 형제 또는 사랑하는 사람에 대한 용서.", "하룬 (AS)을 위한 무사 (AS)의 듀아입니다."),
        "dua_q_ufawwidu_amri" to DuaText("나는 내 일을 알라에게 맡깁니다.", "그리고 나는 나의 일을 알라에게 맡깁니다. 실제로 알라는 그의 종들의 모든 것을 보시는 분입니다.", "사람들이 당신을 반대할 때 문제는 알라에게 맡겨야 합니다.", "바로의 백성 중 믿는 자의 말이라. 그런 다음 알라는 그들의 사악한 음모로부터 그를 보호했습니다."),
        "dua_q_hawariyyun" to DuaText("제자들의 두아 — 증인들과 함께 우리를 기록하세요", "주님, 저희는 당신께서 계시하신 것을 믿고 선지자를 따랐으니 저희를 증인으로 기록해 주소서.", "믿음의 확고함과 메신저를 따르는 것.", "이사야 (AS)년의 제자들의 두아."),
        "dua_q_la_tukhzini" to DuaText("이브라힘의 두아 (AS) — 나를 모욕하지 마십시오", "그리고 그들이 부활하는 날에 나를 모욕하지 마십시오.", "부활의 날에 치욕을 당하지 않게 하소서.", "내세를 위한 이브라힘 (AS)의 듀아."),
        "dua_iftar_laka_sumtu" to DuaText("Iftar — 당신을 위해 단식했습니다", "오 알라, 나는 당신을 위해 금식했고 당신의 공급하심으로 금식을 깨뜨렸습니다.", "단식을 깨는 경우(잘 알려진 iftar dua).", "예언자 ﷺ은 iftar에서 이렇게 말했습니다. 다른 서사를 통해 강화된 머살 서사이다. iftar에서 그것을 낭송하는 것은 Hanafis와 대다수의 관행입니다."),
        "dua_iftar_ibn_umar" to DuaText("Iftar — 당신의 크신 자비로 나를 용서하소서", "오 알라시여, 모든 것을 포괄하는 당신의 자비로 저를 용서해 주시기를 청합니다.", "iftar에서 — Abdullah ibn Amr (RA)이 이 dua를 만들었습니다. iftar에서 단식하는 사람의 이중은 거부되지 않습니다.", "하디스: 이프타르 당시 단식하는 사람의 두아(dua)는 거부되지 않습니다."),
        "dua_inni_saim" to DuaText("단식 중에 화가 났을 때", "나는 금식하고 있습니다. 나는 금식하고 있습니다.", "금식 중에 누군가가 여러분을 모욕하거나 다투었을 때.", "선지자 ﷺ은 다음과 같이 말했습니다: 금식은 방패이므로 금식하는 사람은 음란하게 말하거나 무지하게 행동해서는 안 됩니다. 누군가가 다투면 이 말을 두 번 말하십시오."),
        "dua_eid_takbeer" to DuaText("Eid로 가는 길의 Takbeer", "알라는 가장 위대하시며, 알라는 가장 위대하시며, 알라 외에는 신이 없으며, 알라는 가장 위대하시며, 알라는 가장 위대하시며, 모든 찬양은 알라에게 있습니다.", "달 관찰의 밤부터 Eid al-Fitr 기도까지, 특히 Eid 땅으로 가는 길에.", "꾸란 명령: '그리하여 너희는 계산을 완료하고 알라의 위대함을 선포하라'(알-바카라 2:185). Ibn Mas'ud (RA)이 takbir을 말했습니다."),
        "dua_ahsin_aqibatana" to DuaText("모든 일에서 우리의 결말을 좋게 하라", "오 알라여, 우리의 모든 일이 좋게 끝나게 하시고 현세의 치욕과 내세의 형벌로부터 우리를 보호하소서.", "모든 일에 좋은 결과가 있기를 바랍니다.", "이 이중을 만들고 재판을 받기 전에 죽는 사람은 누구나 죽습니다(재판으로부터 안전함)."),
        "dua_fadlika_wa_rahmatik" to DuaText("나는 당신의 은혜와 자비를 구합니다", "오 알라, 나는 당신에게 당신의 관대함과 자비를 구합니다. 왜냐하면 당신 외에는 그것을 소유할 자가 없기 때문입니다.", "공급과 자비를 구할 때.", "음식이 없을 때 손님이 선지자 ﷺ에게 왔습니다. 그가 이 듀아를 만들었고 선물이 도착했어요."),
        "dua_allahu_akbar_kabira_2696" to DuaText("베두인에게 가르치는 말씀", "어떠한 동반자도 없는 유일한 알라 외에는 경배받을 분이 없습니다. 알라는 가장 위대하십니다. 알라에게는 풍성한 찬양이 있습니다. 세상의 주님이신 알라께 영광을 돌립니다. 전능하시고 지혜로우신 알라 외에는 힘도 능력도 없습니다.", "dhikr 및 dua의 포괄적인 문구 — 베두인에게 가르칩니다.", "그 후 그는 'Allahummaghfir li warhamni wahdini warzuqni'라고 말하는 법을 배웠습니다."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("내가 보낸 전후를 용서하세요", "오 알라시여, 제가 이전과 이후에 지은 죄들, 내가 은밀히 행한 것과 공개적으로 행한 것, 나의 과잉, 그리고 당신이 나보다 더 잘 아시는 것을 용서해 주십시오. 당신은 앞으로 가져오시는 분이시며 뒤로 물러나게 하시는 분입니다. 당신 외에는 신이 없습니다.", "tashahhud와 salawat 이후, salam 이전.", "선지자 ﷺ은 기도 마지막 부분인 타샤후드와 살람 사이에서 이것을 낭송했습니다."),
        "dua_jiddi_wa_hazli" to DuaText("나의 진지함과 농담을 용서해주세요", "오 알라, 제가 진지하게, 농담으로, 실수로, 고의로 저지른 죄를 용서해 주십시오. 그리고 그 모든 것은 제 안에 있습니다.", "알려지거나 알려지지 않은 모든 종류의 죄에 대한 용서입니다.", "선지자 ﷺ의 포괄적인 istighfar입니다."),
        "dua_rising_ruku_mil" to DuaText("After Ruku — 하늘을 채우는 찬양", "우리 주여, 하늘을 채우고 땅을 채우고 그 후에 당신이 원하시는 모든 것을 채우는 모든 찬양이 당신께 속합니다.", "Ruku에서 상승한 후 'Rabbana lakal-hamd'와 함께.", "예언자 ﷺ은 루쿠에서 일어나면서 이렇게 말했습니다."),
        "dua_istiftah_kabira" to DuaText("알라는 가장 위대하시고, 풍성히 찬양받으신다", "알라는 가장 위대하십니다. 알라에게는 풍성한 찬양이 있습니다. 아침과 저녁으로 알라께 영광이 있기를 바랍니다.", "기도를 시작할 때(개회 찬양의 한 형태)", "선지자 ﷺ은 이렇게 말했습니다: 천국의 문이 그것을 위해 열렸습니다."),
        "dua_q_ashku_bathhi" to DuaText("Dua of Yaqub (AS) — 나는 오직 알라에게만 불평합니다", "나는 내 괴로움과 슬픔을 오직 알라께만 호소합니다.", "깊은 슬픔과 이별 속에서.", "Ya'qub (AS)은 Yusuf (AS)과 헤어지면서 이렇게 말했습니다."),
        "dua_q_khayrun_hafiza" to DuaText("알라는 최고의 보호자이다", "알라는 최고의 보호자이시며 자비로운 자 중에 가장 자비로우신 분이십니다.", "어린이나 사랑하는 사람을 여행에 보낼 때.", "Ya'qub (AS)은 그의 아들을 알라에게 맡기면서 이렇게 말했습니다."),
        "dua_q_aqraba_rashada" to DuaText("나의 주님께서 나를 올바른 방향으로 더 가까이 인도하시기를 바랍니다", "아마도 나의 주님께서는 이보다 올바른 행동에 더 가까운 것으로 나를 인도하실 것입니다.", "어떤 문제에서 더 나은 방법을 찾을 때.", "예언자 ﷺ은 잊어버렸을 때 이렇게 말하라는 지시를 받았습니다."),
        "dua_q_sawa_as_sabil" to DuaText("Dua of Musa (AS) — 나를 올바른 길로 인도해주세요", "아마도 나의 주님께서 나를 올바른 길로 인도하실 것입니다.", "새로운 여행을 떠날 때나 낯선 길을 떠날 때.", "무사 (AS)은 마디안을 향해 몸을 돌리면서 이렇게 말했습니다."),
        "dua_q_not_among_wrongdoers" to DuaText("나를 범죄자 가운데 두지 마십시오", "주님, 저를 불의한 사람들 가운데 두지 마십시오.", "알라에게 범죄자들로부터 자신을 분리해 달라고 요청하는 두아.", "알라에게 범죄자들로부터 자신을 분리해 달라고 요청하는 두아."),
        "dua_q_do_not_make_us_trial" to DuaText("우리를 시련으로 만들지 마십시오", "우리 주님, 불신자들에게 우리를 시험하지 않게 하시고, 우리 주님을 용서해 주십시오. 진실로 당신은 전능하시고 지혜로우신 분이십니다.", "이브라힘 (AS)과 그의 동료들의 두아.", "이브라힘 (AS)과 그의 동료들의 두아."),
        "dua_morning_witness" to DuaText("Tawhid의 아침 증인", "오 알라, 나는 아침에 당신과 당신의 보좌를 맡은 자들과 당신의 천사들과 당신의 모든 창조물을 부르며 당신이 알라이시며, 당신 외에는 신이 없으며, 홀로, 파트너 없이, 그리고 무함마드 ﷺ이 당신의 종이자 메신저임을 증언하기 위해 들어섰습니다.", "내레이션에는 아침에 네 번이나 말하는 것이 언급되어 있습니다.", "내레이션에는 아침에 네 번이나 말하는 것이 언급되어 있습니다."),
    )
}
